import json


def parse_call(reply, tools):
    name = reply.get('name')
    if name not in tools:
        return ('error', f"unknown tool '{name}'; available: {', '.join(sorted(tools))}")
    try:
        args = json.loads(reply.get('arguments', ''))
    except json.JSONDecodeError as e:
        return ('error', f'arguments are not valid JSON: {e.msg}')
    errors = validate(args, tools[name]['schema'])
    if errors:
        return ('error', '; '.join(errors))
    return ('ok', name, args)


def run_call(name, args, tools):
    try:
        return ('ok', tools[name]['fn'](**args))
    except Exception as e:
        return ('error', f'{name} failed: {e}')

